import csv
path='/root/weoapr2025all.xls'
with open(path,'r',encoding='utf-16-le') as f:
    reader=csv.reader(f, delimiter='\t')
    header=next(reader)
    year_idx={y:i for i,y in enumerate(header) if y.isdigit()}
    years=[str(y) for y in range(2020, 2031)]
    data={}
    for row in reader:
        if len(row)>3 and row[3]=='Georgia' and row[2] in ('NGDP_R','NGDP_RPCH','NGDP_D','NGDP'):
            code=row[2]
            data[code]={y: row[year_idx[y]] for y in years}
    print('codes', data.keys())
    for code in data:
        print(code)
        for y in years:
            print(y, data[code][y])
        print('---')
